package com.example.rokidgeminisecretary;
import android.content.*;import android.media.*;import org.json.*;import java.io.*;import java.nio.*;import java.nio.file.*;
/** Encrypted chunk upload and bounded audio-only decoding. Never loads the entire video. */
final class MeetingMediaImport {
 static final int CHUNK=524288;static final long MAX_FILE=2147483648L;static volatile String active="";
 static File root(Context c){File f=new File(c.getFilesDir(),"meeting-import");f.mkdirs();return f;}
 static File folder(Context c,String id)throws IOException {if(!id.matches("[0-9]{13}-[a-f0-9-]{36}"))throw new IOException("読み込みIDが不正です");return new File(root(c),id);}
 static JSONObject job(File f)throws Exception{return new JSONObject(new String(Files.readAllBytes(new File(f,"job.json").toPath()),"UTF-8"));}
 static void save(File f,JSONObject j)throws Exception{MeetingAudioStore.write(new File(f,"job.json"),j.toString().getBytes("UTF-8"));}
 static void removeParts(File f)throws IOException{File[] files=f.listFiles();if(files!=null)for(File x:files)if(x.getName().matches("[0-9]{5}\\.gcm"))if(!x.delete())throw new IOException("一時録画データを削除できません");}
 static synchronized JSONObject begin(Context c,JSONObject input)throws Exception{
  long size=input.getLong("size");if(size<1||size>MAX_FILE)throw new IOException("ファイルは2GB以下にしてください");
  File[] previous=root(c).listFiles();if(previous!=null)for(File f:previous){JSONObject j=job(f);if(j.optString("state").equals("uploading")&&System.currentTimeMillis()-j.optLong("createdAt")>86400000){removeParts(f);j.put("state","expired").put("status","アップロード期限切れ");save(f,j);}else if(j.optString("state").equals("uploading")||j.optString("state").equals("converting")){if(j.optString("state").equals("converting")&&!f.getName().equals(active)){j.put("state","interrupted").put("status","音声抽出中断：再試行してください");save(f,j);}else throw new IOException("別のファイルを読み込み中です。完了または取消を待ってください");}}
  if(root(c).getUsableSpace()<size+340000000L)throw new IOException("スマホの空き容量が不足しています");
  String id=System.currentTimeMillis()+"-"+java.util.UUID.randomUUID();File f=folder(c,id);if(!f.mkdirs())throw new IOException("読み込み先を作成できません");String title=input.optString("name","読み込んだ録画・録音");if(title.length()>120)title=title.substring(0,120);
  JSONObject j=new JSONObject().put("id",id).put("title",title).put("size",size).put("chunks",(size+CHUNK-1)/CHUNK).put("next",0).put("createdAt",System.currentTimeMillis()).put("state","uploading").put("status","アップロード中");save(f,j);return j.put("chunkSize",CHUNK);
 }
 static synchronized JSONObject chunk(Context c,JSONObject packet)throws Exception{
  File f=folder(c,packet.getString("id"));JSONObject j=job(f);if(!j.getString("state").equals("uploading"))throw new IOException("アップロードは受付終了しています");
  int index=packet.getInt("index"),next=j.getInt("next");if(index<0||index>next||index>=j.getInt("chunks"))throw new IOException("転送順序が一致しません");String encoded=packet.getString("data");if(encoded.length()>700000)throw new IOException("転送区間が大きすぎます");byte[] bytes=android.util.Base64.decode(encoded,android.util.Base64.URL_SAFE|android.util.Base64.NO_WRAP);int expected=(int)Math.min(CHUNK,j.getLong("size")-(long)index*CHUNK);String sha=RecorderPhotoStore.hash(bytes);if(bytes.length!=expected||!sha.equals(packet.getString("sha")))throw new IOException("録画ファイルの転送ハッシュ不一致");File target=new File(f,String.format(java.util.Locale.US,"%05d.gcm",index));
  if(index<next){byte[] old=DeviceSecrets.photos().decrypt(Files.readAllBytes(target.toPath()));if(!java.util.Arrays.equals(bytes,old))throw new IOException("転送内容が競合しています");}
  else{if(f.getUsableSpace()<100000000)throw new IOException("スマホの空き容量が不足しています");MeetingAudioStore.write(target,DeviceSecrets.photos().encrypt(bytes));j.put("next",next+1);save(f,j);}return new JSONObject().put("ok",true).put("sha",sha).put("next",j.getInt("next"));
 }
 static synchronized JSONObject list(Context c)throws Exception{JSONArray items=new JSONArray();File[] folders=root(c).listFiles();if(folders!=null){java.util.Arrays.sort(folders,(a,b)->b.getName().compareTo(a.getName()));for(File f:folders){JSONObject j=job(f);if(j.optString("state").equals("converting")&&!f.getName().equals(active)){j.put("state","interrupted").put("status","音声抽出中断：再試行してください");save(f,j);}items.put(j);}}return new JSONObject().put("items",items);}
 static synchronized void cancel(Context c,String id)throws Exception {if(id.equals(active))throw new IOException("音声抽出中です。完了を待ってください");File f=folder(c,id);JSONObject j=job(f);if(j.optString("state").equals("complete"))throw new IOException("読み込み済みの記録は保持します");removeParts(f);j.put("state","cancelled").put("status","読み込みを取り消しました");save(f,j);}
 static synchronized void finish(Context c,String id)throws Exception{
  if(!active.isEmpty()||MeetingAudioStore.busy())throw new IOException("別のファイルまたは会議を処理中です");File f=folder(c,id);JSONObject j=job(f);String state=j.getString("state");if(state.equals("complete"))return;if(!(state.equals("uploading")||state.equals("interrupted")||state.equals("failed"))||j.getInt("next")!=j.getInt("chunks"))throw new IOException("ファイルの転送が完了していません");
  active=id;j.put("state","converting").put("status","録画・録音から音声抽出中");save(f,j);
  try{c.startForegroundService(new Intent(c,MeetingProcessingService.class).putExtra("id",id));}catch(Exception e){active="";j.put("state","failed").put("status","音声抽出を開始できません。スマホでロキを開いて再試行してください");save(f,j);throw new IOException(j.getString("status"));}
 }
 static final class EncryptedSource extends MediaDataSource {
  final File folder;final long size;int cached=-1;byte[] data;
  EncryptedSource(File f,long bytes){folder=f;size=bytes;}
  public synchronized int readAt(long position,byte[] buffer,int offset,int count)throws IOException{
   if(position<0||offset<0||count<0||offset+count>buffer.length)throw new IOException("invalid media read");if(count==0)return 0;if(position>=size)return -1;int wanted=(int)Math.min(count,size-position),done=0;
   try{while(done<wanted){int block=(int)((position+done)/CHUNK),at=(int)((position+done)%CHUNK);if(cached!=block){data=DeviceSecrets.photos().decrypt(Files.readAllBytes(new File(folder,String.format(java.util.Locale.US,"%05d.gcm",block)).toPath()));cached=block;}int n=Math.min(wanted-done,data.length-at);if(n<=0)throw new IOException("録画区間が不完全です");System.arraycopy(data,at,buffer,offset+done,n);done+=n;}return done;}catch(Exception e){throw new IOException("録画データを復号できません",e);}
  }
  public long getSize(){return size;}public synchronized void close(){data=null;cached=-1;}
 }
 static final class PcmWriter {
  final Context c;final String id;final byte[] part=new byte[320000];final JSONArray parts=new JSONArray();int at,index;long total;double sampleIndex=-1,targetIndex;float previous;int rate,channels,encoding;
  PcmWriter(Context context,String identity){c=context;id=identity;}
  void format(MediaFormat f)throws IOException{int nextRate=f.getInteger(MediaFormat.KEY_SAMPLE_RATE),nextChannels=f.getInteger(MediaFormat.KEY_CHANNEL_COUNT),nextEncoding=f.containsKey(MediaFormat.KEY_PCM_ENCODING)?f.getInteger(MediaFormat.KEY_PCM_ENCODING):AudioFormat.ENCODING_PCM_16BIT;if(nextRate<8000||nextRate>192000||nextChannels<1||nextChannels>8||(nextEncoding!=AudioFormat.ENCODING_PCM_16BIT&&nextEncoding!=AudioFormat.ENCODING_PCM_FLOAT))throw new IOException("未対応の音声形式です");if(total>0&&(rate!=nextRate||channels!=nextChannels||encoding!=nextEncoding))throw new IOException("途中で音声形式が変わりました");rate=nextRate;channels=nextChannels;encoding=nextEncoding;}
  void data(ByteBuffer source)throws Exception{source.order(ByteOrder.LITTLE_ENDIAN);int width=encoding==AudioFormat.ENCODING_PCM_FLOAT?4:2,frame=width*channels;if(source.remaining()%frame!=0)throw new IOException("PCM音声区間が不完全です");while(source.remaining()>=frame){float value=0;for(int ch=0;ch<channels;ch++)value+=encoding==AudioFormat.ENCODING_PCM_FLOAT?source.getFloat()*32767f:source.getShort();value/=channels;if(!Float.isFinite(value))value=0;sampleIndex++;while(targetIndex<=sampleIndex){double fraction=sampleIndex==0?1:targetIndex-(sampleIndex-1);float mono=sampleIndex==0?value:(float)(previous+(value-previous)*fraction);short pcm=(short)Math.max(-32768,Math.min(32767,Math.round(mono)));if(total>=230400000L)throw new IOException("録音は最大2時間です");part[at++]=(byte)pcm;part[at++]=(byte)(pcm>>8);total+=2;if(at==part.length)seal();targetIndex+=rate/16000.0;}previous=value;}}
  void seal()throws Exception{if(at==0)return;byte[] wav=MeetingAudioStore.wav(java.util.Arrays.copyOf(part,at));String sha=RecorderPhotoStore.hash(wav);MeetingAudioStore.accept(c,new JSONObject().put("id",id).put("index",index).put("sha",sha).put("encoding","base64url").put("data",android.util.Base64.encodeToString(wav,android.util.Base64.NO_WRAP|android.util.Base64.URL_SAFE)));parts.put(new JSONObject().put("file",String.format(java.util.Locale.US,"%04d.gcm",index++)).put("bytes",at).put("sha",sha));at=0;}
 }
 static void convert(Context c,String id)throws Exception{
  File f=folder(c,id);JSONObject j=job(f);File audio=MeetingAudioStore.folder(c,id);if(new File(audio,"session.json").exists())throw new IOException("既存の記録を上書きできません");if(audio.exists()){File[] stale=audio.listFiles();if(stale!=null)for(File part:stale){if(!part.getName().matches("[0-9]{4}\\.gcm"))throw new IOException("読み込み先が競合しています");if(!part.delete())throw new IOException("前回の音声抽出を再開できません");}}
  MediaExtractor extractor=new MediaExtractor();MediaCodec decoder=null;PcmWriter writer=new PcmWriter(c,id);
  try(EncryptedSource source=new EncryptedSource(f,j.getLong("size"))){extractor.setDataSource(source);int track=-1;MediaFormat input=null;for(int i=0;i<extractor.getTrackCount();i++){MediaFormat format=extractor.getTrackFormat(i);if(format.getString(MediaFormat.KEY_MIME).startsWith("audio/")){track=i;input=format;break;}}if(track<0)throw new IOException("録画ファイルに音声がありません");if(input.containsKey(MediaFormat.KEY_DURATION)&&input.getLong(MediaFormat.KEY_DURATION)>7200000000L)throw new IOException("録画・録音は最大2時間です");extractor.selectTrack(track);input.setInteger(MediaFormat.KEY_PCM_ENCODING,AudioFormat.ENCODING_PCM_16BIT);decoder=MediaCodec.createDecoderByType(input.getString(MediaFormat.KEY_MIME));decoder.configure(input,null,null,0);decoder.start();boolean inputEnd=false,outputEnd=false;MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();long lastOutput=android.os.SystemClock.elapsedRealtime(),lastProgress=0;
   while(!outputEnd){if(Thread.currentThread().isInterrupted())throw new IOException("音声抽出が中断されました");if(!inputEnd){int index=decoder.dequeueInputBuffer(10000);if(index>=0){ByteBuffer buffer=decoder.getInputBuffer(index);int bytes=extractor.readSampleData(buffer,0);if(bytes<0){decoder.queueInputBuffer(index,0,0,0,MediaCodec.BUFFER_FLAG_END_OF_STREAM);inputEnd=true;}else{if((extractor.getSampleFlags()&MediaExtractor.SAMPLE_FLAG_ENCRYPTED)!=0)throw new IOException("保護された録画には対応していません");decoder.queueInputBuffer(index,0,bytes,extractor.getSampleTime(),0);extractor.advance();}}}
    int output=decoder.dequeueOutputBuffer(info,10000);if(output==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED){writer.format(decoder.getOutputFormat());lastOutput=android.os.SystemClock.elapsedRealtime();}else if(output>=0){try{if(info.size>0&&(info.flags&MediaCodec.BUFFER_FLAG_CODEC_CONFIG)==0){if(writer.rate==0)writer.format(decoder.getOutputFormat());ByteBuffer pcm=decoder.getOutputBuffer(output);pcm.position(info.offset);pcm.limit(info.offset+info.size);writer.data(pcm.slice());lastOutput=android.os.SystemClock.elapsedRealtime();}outputEnd=(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0;}finally{decoder.releaseOutputBuffer(output,false);}}
    long now=android.os.SystemClock.elapsedRealtime();if(now-lastOutput>30000)throw new IOException("音声抽出が30秒停止しました");if(now-lastProgress>1000){j.put("status","音声抽出中："+writer.total/32000+"秒");save(f,j);lastProgress=now;}
   }
   writer.seal();if(writer.total<2)throw new IOException("読み取れる音声がありません");JSONObject meta=new JSONObject().put("id",id).put("startedAt",j.getLong("createdAt")).put("state","stopped").put("title",j.getString("title")).put("source","media-import").put("parts",writer.parts).put("pcmBytes",writer.total).put("reason","録画・録音ファイルから読み込み").put("topics",new JSONArray());MeetingAudioStore.accept(c,new JSONObject().put("id",id).put("manifest",meta));removeParts(f);j.put("state","complete").put("status","音声抽出完了：文字起こし・AI要約を開始できます").put("durationMs",writer.total/32);save(f,j);
  }finally{if(decoder!=null){try{decoder.stop();}catch(Exception ignored){}decoder.release();}extractor.release();}
 }
 static void failed(Context c,String id,Exception error){try{File f=folder(c,id);JSONObject j=job(f);j.put("state","failed").put("status","音声抽出失敗："+(error instanceof IOException?error.getMessage():"この録画・録音形式を読み取れません")+"。再試行または取消してください");save(f,j);}catch(Exception ignored){}}
}